      find.byWidgetPredicate(
        (Widget widget) {
          if (widget is! ConstrainedBox) return false;
          final BoxConstraints c = widget.constraints;
          return c.minWidth == 48.0 &&
              c.minHeight == 32.0 &&
              c.maxWidth == 420.0 &&
              c.maxHeight == 240.0;
        },
        skipOffstage: false,
